const GROUND={'.':{ground:'grass',plan:'lawn'},',':{ground:'grass',plan:'meadow'},'d':{ground:'trail',plan:'dirt'},'p':{ground:'paved',plan:'avenue'},'c':{ground:'paved',plan:'plaza'},'g':{ground:'paved',plan:'gravel'},'w':{ground:'water',plan:'pond',block:true},'b':{ground:'bridge',under:'water',bridgeAxis:'vertical',plan:'dock'},'v':{ground:'trail',plan:'farm'}};
const PROPS={T:'oak',A:'orchard',B:'blossom',h:'hedge',f:'fence',L:'lamp',N:'bench',Q:'planter',O:'well',Z:'stall',K:'barrel',X:'crates',U:'statue',s:'scarecrow',r:'rock',M:'mailbox',S:'sign'};
const TREES={oak:1,orchard:1,blossom:1};
